public class MatrixMultiplierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("2x3 times 3x2", "[[58, 64], [139, 154]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(
                            new int[][]{{1, 2, 3}, {4, 5, 6}},
                            new int[][]{{7, 8}, {9, 10}, {11, 12}})));
            check("3x2 times 2x3", "[[9, 12, 15], [19, 26, 33], [29, 40, 51]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(
                            new int[][]{{1, 2}, {3, 4}, {5, 6}},
                            new int[][]{{1, 2, 3}, {4, 5, 6}})));
            int[][] m = {{3, -1}, {2, 5}};
            int[][] identity = {{1, 0}, {0, 1}};
            check("m times identity equals m", "[[3, -1], [2, 5]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(m, identity)));
            check("identity times m equals m", "[[3, -1], [2, 5]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(identity, m)));
            check("1x1 times 1x1", "[[42]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(
                            new int[][]{{6}}, new int[][]{{7}})));
            check("2x2 order matters (a*b)", "[[4, 4], [11, 10]]",
                    java.util.Arrays.deepToString(MatrixMultiplier.multiply(
                            new int[][]{{1, 1}, {2, 3}}, new int[][]{{1, 2}, {3, 2}})));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

